-- Seed data for airline_booking. Run after the schema/migrations have created all tables.
-- Password hashes below are placeholders; replace them with BCrypt hashes generated by your application.
USE airline_booking;
SET FOREIGN_KEY_CHECKS = 1;
START TRANSACTION;



-- Resolve existing role IDs by name.
SELECT seed.user_id, roles.id
FROM (
    SELECT '00000002-0000-4000-8000-000000000001' AS user_id, 'ADMIN' AS role_name
    UNION ALL SELECT '00000002-0000-4000-8000-000000000002', 'CUSTOMER'
    UNION ALL SELECT '00000002-0000-4000-8000-000000000003', 'CUSTOMER'
    UNION ALL SELECT '00000002-0000-4000-8000-000000000004', 'CUSTOMER'
    UNION ALL SELECT '00000002-0000-4000-8000-000000000005', 'STAFF'
) AS seed
JOIN roles ON roles.name = seed.role_name;










COMMIT;

-- Quick checks
SELECT COUNT(*) AS airport_count FROM airports;
SELECT COUNT(*) AS flight_count FROM flights;
SELECT COUNT(*) AS schedule_count FROM flight_schedules;
SELECT COUNT(*) AS flight_seat_count FROM flight_seats;
SELECT COUNT(*) AS booking_count FROM bookings;

-- Example search query
SELECT
    f.flight_number,
    dep.code AS departure_code,
    arr.code AS arrival_code,
    fs.departure_time,
    fs.arrival_time,
    fs.base_price,
    SUM(CASE WHEN fss.status = 'AVAILABLE' THEN 1 ELSE 0 END) AS available_seats
FROM flights f
JOIN airports dep ON dep.id = f.departure_airport_id
JOIN airports arr ON arr.id = f.arrival_airport_id
JOIN flight_schedules fs ON fs.flight_id = f.id
JOIN flight_seats fss ON fss.flight_schedule_id = fs.id
WHERE dep.code = 'SGN'
  AND arr.code = 'HAN'
  AND fs.status IN ('SCHEDULED', 'BOARDING')
GROUP BY f.id, f.flight_number, dep.code, arr.code,
         fs.id, fs.departure_time, fs.arrival_time, fs.base_price
ORDER BY fs.departure_time;